-- TO-143-D3 driver model: agency_driver_employment is the single authority.
--
-- GENERATED by scripts/gen_driver_model_migration.mjs. Owner decision
-- 2026-11-04 (advisor-recommended):
--   1. Backfill an ACTIVE employment row for every approved driver already
--      linked through agency_trucks.driver_id. Hard cases STOP the migration
--      with a listing (driver employed by another agency, driver not approved);
--      nothing is invented and nothing is partially written.
--   2. driver_is_assigned_to_agency() now means "active employment in that
--      agency"; the agency_jobs and agency_pay payout guards switch together.
--   3. agency_trucks.driver_id stays only as a default truck-driver pairing and
--      may be set only for an actively employed driver; ending employment
--      clears it.
--   4. reserve_fleet_assignment projects onto agency_jobs.truck_id/driver_id;
--      release / offer decline|expire|cancel clear them only while they still
--      match the reservation; a consumed reservation keeps them.
--   5. agency_driver_employment_end refuses with driver_has_active_assignment
--      while the employment holds an active reservation.

-- ---------------------------------------------------------------------------
-- 1. Backfill (stop-and-list on conflicts)
-- ---------------------------------------------------------------------------
DO $backfill$
DECLARE
  v_blocked text;
BEGIN
  SELECT string_agg(
           format('%s (agency %s, %s)', c.driver_id, c.agency_id, c.reason),
           '; ' ORDER BY c.driver_id)
    INTO v_blocked
  FROM (
    SELECT DISTINCT t.driver_id, t.agency_id,
           CASE
             WHEN NOT public.driver_is_approved_for_assignment(t.driver_id) THEN 'driver not approved'
             ELSE 'driver actively employed by another agency'
           END AS reason
    FROM public.agency_trucks t
    WHERE t.driver_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.agency_driver_employment e
        WHERE e.driver_id = t.driver_id AND e.agency_id = t.agency_id AND e.status = 'active'
      )
      AND (
        NOT public.driver_is_approved_for_assignment(t.driver_id)
        OR EXISTS (
          SELECT 1 FROM public.agency_driver_employment e2
          WHERE e2.driver_id = t.driver_id AND e2.agency_id <> t.agency_id AND e2.status = 'active'
        )
      )
  ) c;

  IF v_blocked IS NOT NULL THEN
    RAISE EXCEPTION 'Driver model backfill blocked: %', v_blocked;
  END IF;

  INSERT INTO public.agency_driver_employment (agency_id, driver_id, status)
  SELECT DISTINCT ON (t.driver_id) t.agency_id, t.driver_id, 'active'
  FROM public.agency_trucks t
  WHERE t.driver_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.agency_driver_employment e
      WHERE e.driver_id = t.driver_id AND e.status = 'active'
    )
  ORDER BY t.driver_id, t.created_at;
END
$backfill$;

-- ---------------------------------------------------------------------------
-- 2. Authority guard: employment replaces the truck link
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.driver_is_assigned_to_agency(p_driver_id uuid, p_agency_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.agency_driver_employment e
    WHERE e.driver_id = p_driver_id
      AND e.agency_id = p_agency_id
      AND e.status = 'active'
  );
$$;

-- ---------------------------------------------------------------------------
-- 3-5. Patched functions
-- ---------------------------------------------------------------------------
-- enforce_agency_truck_driver_assignment (from 20261006120000_tenant_authority_repair.sql, patched)
CREATE OR REPLACE FUNCTION public.enforce_agency_truck_driver_assignment()
RETURNS TRIGGER AS $$
DECLARE
  v_other_agency uuid;
BEGIN
  IF public.is_admin_user() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.driver_id IS NOT DISTINCT FROM OLD.driver_id THEN
    RETURN NEW;
  END IF;

  IF NEW.driver_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT public.driver_is_approved_for_assignment(NEW.driver_id) THEN
    RAISE EXCEPTION 'Driver is not approved for assignment.';
  END IF;

  -- Pinned duplicate rule: a driver holds at most one truck row globally.
  v_other_agency := public.driver_other_truck_agency_id(NEW.driver_id, NEW.id, NEW.agency_id);
  IF v_other_agency IS NOT NULL THEN
    IF v_other_agency <> NEW.agency_id THEN
      RAISE EXCEPTION 'Driver is already assigned to another agency.';
    END IF;
    RAISE EXCEPTION 'Driver is already assigned to another truck.';
  END IF;

  IF NOT public.driver_is_assigned_to_agency(NEW.driver_id, NEW.agency_id) THEN
    RAISE EXCEPTION 'Driver is not employed by this agency.';
  END IF;

  IF NOT public.agency_is_operational(NEW.agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- reserve_fleet_assignment (from 20261012000000_staff_scope_enforcement.sql, patched)
CREATE OR REPLACE FUNCTION public.reserve_fleet_assignment(
  p_agency_job_id uuid,
  p_job_offer_id uuid,
  p_vehicle_id uuid,
  p_driver_employment_id uuid,
  p_window_start timestamptz,
  p_window_end timestamptz,
  p_expected_vehicle_version integer,
  p_idempotency_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_now timestamptz := NOW();
  v_job public.agency_jobs%ROWTYPE;
  v_employment public.agency_driver_employment%ROWTYPE;
  v_vehicle public.agency_trucks%ROWTYPE;
  v_offer public.job_offers%ROWTYPE;
  v_existing public.fleet_assignment_reservations%ROWTYPE;
  v_inserted public.fleet_assignment_reservations%ROWTYPE;
  v_message text;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['dispatcher']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  IF p_window_start IS NULL OR p_window_end IS NULL THEN
    RAISE EXCEPTION 'Reservation window is required.';
  END IF;

  IF p_window_end <= p_window_start THEN
    RAISE EXCEPTION 'Reservation window must end after it starts.';
  END IF;

  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'Idempotency key is required.';
  END IF;

  -- (a) Idempotent replay, scoped to the caller agency. Same key + same request
  --     returns the stored reservation; same key + different request is refused.
  SELECT * INTO v_existing
  FROM public.fleet_assignment_reservations
  WHERE agency_id = v_agency_id
    AND idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.agency_job_id = p_agency_job_id
       AND v_existing.job_offer_id = p_job_offer_id
       AND v_existing.vehicle_id = p_vehicle_id
       AND v_existing.driver_employment_id = p_driver_employment_id
       AND v_existing.window_start = p_window_start
       AND v_existing.window_end = p_window_end THEN
      RETURN jsonb_build_object(
        'ok', true,
        'state', 'idempotent_replay',
        'reservation', to_jsonb(v_existing),
        'version', v_existing.version
      );
    END IF;

    RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_reused');
  END IF;

  -- (b) Settle this agency's stale offers first, so an expired hold never blocks.
  PERFORM public.release_stale_fleet_reservations(v_agency_id, v_now);

  -- (c) Caller-owned job, employment and vehicle. Foreign ids fail closed as
  --     not found, never as a different denial.
  SELECT * INTO v_job
  FROM public.agency_jobs
  WHERE id = p_agency_job_id
    AND agency_id = v_agency_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Agency job not found or access denied.';
  END IF;

  SELECT * INTO v_employment
  FROM public.agency_driver_employment
  WHERE id = p_driver_employment_id
    AND agency_id = v_agency_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Employment record not found or access denied.';
  END IF;

  SELECT * INTO v_vehicle
  FROM public.agency_trucks
  WHERE id = p_vehicle_id
    AND agency_id = v_agency_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vehicle not found or access denied.';
  END IF;

  IF v_job.status NOT IN ('pending', 'accepted') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'agency_job_not_open');
  END IF;

  -- (d) Expected vehicle version: the caller acted on a stale vehicle state.
  IF v_vehicle.version <> p_expected_vehicle_version THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'version_conflict',
      'current_version', v_vehicle.version
    );
  END IF;

  -- (e) TO-144-D1 eligibility, evaluated at BOTH window edges. The vehicle
  --     predicate covers availability, maintenance flag and blocked-until,
  --     and document expiry; the driver predicate covers active employment for
  --     this agency, approval and licence validity.
  IF NOT (
    public.agency_vehicle_allocation_eligible(p_vehicle_id, p_window_start)
    AND public.agency_vehicle_allocation_eligible(p_vehicle_id, p_window_end)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'vehicle_not_eligible');
  END IF;

  IF NOT (
    public.agency_driver_allocation_eligible(v_employment.driver_id, v_agency_id, p_window_start)
    AND public.agency_driver_allocation_eligible(v_employment.driver_id, v_agency_id, p_window_end)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'driver_not_eligible');
  END IF;

  -- (f) The offer must be live for this job's shipment and this driver:
  --     pending and unexpired, or already accepted.
  SELECT * INTO v_offer
  FROM public.job_offers
  WHERE id = p_job_offer_id;

  IF NOT FOUND
     OR v_offer.shipment_id IS DISTINCT FROM v_job.shipment_id
     OR v_offer.driver_id IS DISTINCT FROM v_employment.driver_id
     OR NOT (
       v_offer.status = 'accepted'
       OR (v_offer.status = 'pending' AND v_offer.expires_at > v_now)
     ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'offer_not_active');
  END IF;

  -- (g) One active assignment per agency job (the partial unique index is the
  --     backstop for a concurrent insert, handled below).
  IF EXISTS (
    SELECT 1
    FROM public.fleet_assignment_reservations r
    WHERE r.agency_job_id = p_agency_job_id
      AND r.status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'agency_job_already_assigned');
  END IF;

  -- (h) Write. The reservation is the authority for vehicle/driver allocation.
  --     agency_jobs.truck_id / driver_id are NOT written here: the TO-142 guard
  --     trg_agency_jobs_driver_assignment only admits a driver already on the
  --     legacy agency_trucks.driver_id model, which is a separate relationship
  --     from agency_driver_employment (see the header, section 7). The overlap
  --     guard raises inside the INSERT; the EXCEPTION block turns that into a
  --     typed result with nothing written.
  BEGIN
    INSERT INTO public.fleet_assignment_reservations (
      agency_id, agency_job_id, job_offer_id, vehicle_id, driver_employment_id, driver_id,
      window_start, window_end, status, idempotency_key
    ) VALUES (
      v_agency_id, p_agency_job_id, p_job_offer_id, p_vehicle_id, v_employment.id, v_employment.driver_id,
      p_window_start, p_window_end, 'active', p_idempotency_key
    )
    RETURNING * INTO v_inserted;
  EXCEPTION
    WHEN exclusion_violation THEN
      GET STACKED DIAGNOSTICS v_message = MESSAGE_TEXT;
      IF v_message LIKE 'Vehicle reservation%' THEN
        RETURN jsonb_build_object('ok', false, 'error', 'vehicle_reserved');
      END IF;
      RETURN jsonb_build_object('ok', false, 'error', 'driver_reserved');
    WHEN unique_violation THEN
      SELECT * INTO v_existing
      FROM public.fleet_assignment_reservations
      WHERE agency_id = v_agency_id
        AND idempotency_key = p_idempotency_key;

      IF FOUND THEN
        IF v_existing.agency_job_id = p_agency_job_id
           AND v_existing.job_offer_id = p_job_offer_id
           AND v_existing.vehicle_id = p_vehicle_id
           AND v_existing.driver_employment_id = p_driver_employment_id
           AND v_existing.window_start = p_window_start
           AND v_existing.window_end = p_window_end THEN
          RETURN jsonb_build_object(
            'ok', true,
            'state', 'idempotent_replay',
            'reservation', to_jsonb(v_existing),
            'version', v_existing.version
          );
        END IF;
        RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_reused');
      END IF;

      RETURN jsonb_build_object('ok', false, 'error', 'agency_job_already_assigned');
  END;

  -- Project the authoritative reservation onto the job (the jobs guard now
  -- admits an actively employed driver).
  UPDATE public.agency_jobs
  SET truck_id = p_vehicle_id,
      driver_id = v_employment.driver_id
  WHERE id = p_agency_job_id
    AND agency_id = v_agency_id;

  RETURN jsonb_build_object(
    'ok', true,
    'state', 'created',
    'reservation', to_jsonb(v_inserted),
    'version', v_inserted.version
  );
END;
$$;

-- release_fleet_assignment (from 20261012000000_staff_scope_enforcement.sql, patched)
CREATE OR REPLACE FUNCTION public.release_fleet_assignment(
  p_reservation_id uuid,
  p_expected_version integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_current public.fleet_assignment_reservations%ROWTYPE;
  v_updated public.fleet_assignment_reservations%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['dispatcher']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT * INTO v_current
  FROM public.fleet_assignment_reservations
  WHERE id = p_reservation_id
    AND agency_id = v_agency_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reservation not found or access denied.';
  END IF;

  -- Exactly-once replay: an already released row, checked with the version the
  -- caller got back from its release, returns without a second write.
  IF v_current.status = 'released' AND v_current.version = p_expected_version THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state', 'already_released',
      'reservation', to_jsonb(v_current),
      'version', v_current.version
    );
  END IF;

  IF v_current.version <> p_expected_version THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'version_conflict',
      'current_version', v_current.version
    );
  END IF;

  IF v_current.status <> 'active' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'reservation_not_active',
      'current_version', v_current.version
    );
  END IF;

  UPDATE public.fleet_assignment_reservations
  SET status = 'released',
      released_reason = 'manual_release'
  WHERE id = p_reservation_id
    AND version = p_expected_version
  RETURNING * INTO v_updated;

  -- Clear the job projection only while it still matches this reservation.
  UPDATE public.agency_jobs j
  SET truck_id = NULL,
      driver_id = NULL
  WHERE j.id = v_updated.agency_job_id
    AND j.truck_id IS NOT DISTINCT FROM v_updated.vehicle_id
    AND j.driver_id IS NOT DISTINCT FROM v_updated.driver_id;

  RETURN jsonb_build_object(
    'ok', true,
    'state', 'released',
    'reservation', to_jsonb(v_updated),
    'version', v_updated.version
  );
END;
$$;

-- release_fleet_reservations_on_offer_transition (from 20261010000000_fleet_assignment_reservations.sql, patched)
CREATE OR REPLACE FUNCTION public.release_fleet_reservations_on_offer_transition()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.status IN ('declined', 'expired', 'cancelled') THEN
    UPDATE public.fleet_assignment_reservations r
    SET status = 'released',
        released_reason = 'offer_' || NEW.status
    WHERE r.job_offer_id = NEW.id
      AND r.status = 'active';

    -- Clear the job projection of the reservations just released, only while
    -- it still matches.
    UPDATE public.agency_jobs j
    SET truck_id = NULL,
        driver_id = NULL
    FROM public.fleet_assignment_reservations r
    WHERE r.job_offer_id = NEW.id
      AND r.status = 'released'
      AND r.released_reason = 'offer_' || NEW.status
      AND j.id = r.agency_job_id
      AND j.truck_id IS NOT DISTINCT FROM r.vehicle_id
      AND j.driver_id IS NOT DISTINCT FROM r.driver_id;
  ELSIF NEW.status = 'delivered' THEN
    UPDATE public.fleet_assignment_reservations r
    SET status = 'consumed'
    WHERE r.job_offer_id = NEW.id
      AND r.status = 'active';
  END IF;

  RETURN NULL;
END;
$$;

-- agency_driver_employment_end (from 20261012000000_staff_scope_enforcement.sql, patched)
CREATE OR REPLACE FUNCTION public.agency_driver_employment_end(
  p_employment_id uuid,
  p_expected_version integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_owned boolean;
  v_current public.agency_driver_employment%ROWTYPE;
  v_updated public.agency_driver_employment%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['fleet_manager']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.agency_driver_employment
    WHERE id = p_employment_id AND agency_id = v_agency_id
  ) INTO v_owned;
  IF NOT v_owned THEN
    RAISE EXCEPTION 'Employment record not found or access denied.';
  END IF;

  -- Exactly-once end: an already-ended row with the matching expected version
  -- replays as already_ended WITHOUT a second write (version stays put).
  SELECT * INTO v_current
  FROM public.agency_driver_employment
  WHERE id = p_employment_id;

  IF v_current.status = 'ended' THEN
    IF v_current.version = p_expected_version THEN
      RETURN jsonb_build_object(
        'ok', true,
        'state', 'already_ended',
        'employment', to_jsonb(v_current),
        'version', v_current.version
      );
    END IF;
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'version_conflict',
      'current_version', v_current.version
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.fleet_assignment_reservations r
    WHERE r.driver_employment_id = p_employment_id
      AND r.agency_id = v_agency_id
      AND r.status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'driver_has_active_assignment');
  END IF;

  UPDATE public.agency_driver_employment e SET
    status = 'ended'
  WHERE e.id = p_employment_id
    AND e.agency_id = v_agency_id
    AND e.version = p_expected_version
  RETURNING * INTO v_updated;

  IF v_updated.id IS NOT NULL THEN
    -- The truck pairing is derived from employment: ending clears it.
    UPDATE public.agency_trucks t
    SET driver_id = NULL
    WHERE t.agency_id = v_agency_id
      AND t.driver_id = v_updated.driver_id;

    RETURN jsonb_build_object(
      'ok', true,
      'state', 'ended',
      'employment', to_jsonb(v_updated),
      'version', v_updated.version
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', false,
    'error', 'version_conflict',
    'current_version', v_current.version
  );
END;
$$;
